export function parseCsv(text) {
  const rows = []
  let row = [], field = '', quoted = false, started = false

  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++ } else quoted = false
      } else field += c
    } else if (c === '"') { quoted = true; started = true }
    else if (c === ',') { row.push(field); field = ''; started = true }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; started = false }
    else if (c !== '\r') { field += c; started = true }
  }
  if (started) { row.push(field); rows.push(row) }
  return rows
}
```

